static void box(HDC d,int l,int t,int r,int b,COLORREF c){auto p=CreatePen(PS_SOLID,1,c);auto o=(HPEN)SelectObject(d,p);SelectObject(d,GetStockObject(HOLLOW_BRUSH));Rectangle(d,l,t,r,b);SelectObject(d,o);DeleteObject(p);}
